PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS cases (id TEXT PRIMARY KEY, case_reference TEXT NOT NULL UNIQUE, fraud_type TEXT NOT NULL, reported_amount TEXT NOT NULL DEFAULT '0', currency TEXT NOT NULL DEFAULT 'ETH', reported_wallet_address TEXT, blockchain TEXT NOT NULL DEFAULT 'ethereum', description TEXT, status TEXT NOT NULL DEFAULT 'new', analysis_status TEXT NOT NULL DEFAULT 'pending', priority_score INTEGER NOT NULL DEFAULT 0, priority_factors TEXT NOT NULL DEFAULT '{}', created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS wallets (id TEXT PRIMARY KEY, address TEXT NOT NULL, chain TEXT NOT NULL, wallet_type TEXT NOT NULL, first_seen_at TEXT, last_seen_at TEXT, created_at TEXT NOT NULL, UNIQUE(address, chain));
CREATE TABLE IF NOT EXISTS case_wallets (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE, wallet_id TEXT NOT NULL REFERENCES wallets(id) ON DELETE CASCADE, role TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(case_id,wallet_id));
CREATE TABLE IF NOT EXISTS transactions (id TEXT PRIMARY KEY, transaction_hash TEXT NOT NULL, chain TEXT NOT NULL, from_wallet_id TEXT NOT NULL REFERENCES wallets(id), to_wallet_id TEXT NOT NULL REFERENCES wallets(id), asset TEXT NOT NULL, amount TEXT NOT NULL, block_number INTEGER, timestamp TEXT NOT NULL, status TEXT NOT NULL, hop INTEGER, created_at TEXT NOT NULL, UNIQUE(transaction_hash,chain));
CREATE TABLE IF NOT EXISTS case_transactions (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE, transaction_id TEXT NOT NULL REFERENCES transactions(id) ON DELETE CASCADE, created_at TEXT NOT NULL, UNIQUE(case_id,transaction_id));
CREATE TABLE IF NOT EXISTS entities (id TEXT PRIMARY KEY, name TEXT NOT NULL, type TEXT NOT NULL, verification_status TEXT NOT NULL, created_at TEXT NOT NULL, UNIQUE(name,type));
CREATE TABLE IF NOT EXISTS wallet_entity_labels (id TEXT PRIMARY KEY, wallet_id TEXT NOT NULL REFERENCES wallets(id), entity_id TEXT NOT NULL REFERENCES entities(id), source TEXT NOT NULL, confidence REAL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS attributions (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE, wallet_id TEXT NOT NULL REFERENCES wallets(id), entity_id TEXT REFERENCES entities(id), match_type TEXT NOT NULL, confidence REAL, evidence TEXT, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS analysis_results (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE, status TEXT NOT NULL, transaction_count INTEGER NOT NULL DEFAULT 0, hop_count INTEGER NOT NULL DEFAULT 0, provider TEXT NOT NULL DEFAULT 'mock', created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS risk_assessments (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE, score INTEGER NOT NULL, level TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS risk_indicators (id TEXT PRIMARY KEY, risk_assessment_id TEXT NOT NULL REFERENCES risk_assessments(id) ON DELETE CASCADE, code TEXT NOT NULL, description TEXT NOT NULL, severity TEXT NOT NULL, evidence TEXT);
CREATE TABLE IF NOT EXISTS priorities (id TEXT PRIMARY KEY, case_id TEXT NOT NULL UNIQUE REFERENCES cases(id) ON DELETE CASCADE, priority_score INTEGER NOT NULL, priority_factors TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS case_relationships (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE, related_case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE, relationship_type TEXT NOT NULL, confidence REAL NOT NULL, evidence TEXT, shared_wallet TEXT, created_at TEXT NOT NULL, UNIQUE(case_id,related_case_id,relationship_type));
CREATE TABLE IF NOT EXISTS alerts (id TEXT PRIMARY KEY, case_id TEXT REFERENCES cases(id) ON DELETE CASCADE, type TEXT NOT NULL, title TEXT NOT NULL, message TEXT NOT NULL, severity TEXT NOT NULL, read INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL, UNIQUE(case_id,type));
CREATE TABLE IF NOT EXISTS investigation_notes (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE, user_id TEXT, note TEXT NOT NULL, created_at TEXT NOT NULL, updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS investigation_reports (id TEXT PRIMARY KEY, case_id TEXT NOT NULL REFERENCES cases(id) ON DELETE CASCADE, content TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY, case_id TEXT REFERENCES cases(id) ON DELETE CASCADE, user_id TEXT, action TEXT NOT NULL, details TEXT, created_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_cases_priority ON cases(priority_score); CREATE INDEX IF NOT EXISTS idx_cases_created ON cases(created_at); CREATE INDEX IF NOT EXISTS idx_wallets_address ON wallets(address); CREATE INDEX IF NOT EXISTS idx_case_relationships_case ON case_relationships(case_id); CREATE INDEX IF NOT EXISTS idx_alerts_created ON alerts(created_at); CREATE INDEX IF NOT EXISTS idx_audit_case ON audit_logs(case_id);
